from decimal import Decimal, ROUND_HALF_UP


def round_money(x):
    return round(x, 2)


def round_money_dec(x):
    return Decimal(str(x)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)


for v in [2.675, 1.005, 0.125, 0.375, 10.0]:
    print(f"round_money({v}) -> {round_money(v)!r}")
    print(f"round_money_dec({v}) -> {round_money_dec(v)!r}")
print(f"round(2.5) -> {round(2.5)!r}")
print(f"round(3.5) -> {round(3.5)!r}")

def dedupe(seq):
    seen = set()
    out = []
    for x in seq:
        if x not in seen:
            seen.add(x)
            out.append(x)
    return out


def dedupe_fast(seq):
    return list(dict.fromkeys(seq))


